import{c as d,Q as e,j as a,m as o}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第十五章：内置命令与自定义命令","description":"按场景记住最常用的斜杠命令，并把自己的提示词变成可复用的命令","frontmatter":{"title":"第十五章：内置命令与自定义命令","description":"按场景记住最常用的斜杠命令，并把自己的提示词变成可复用的命令","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/commands"},"headers":[],"relativePath":"guide/4-advanced-usage/15-builtin-commands.md","filePath":"guide/4-advanced-usage/15-builtin-commands.md"}'),s={name:"guide/4-advanced-usage/15-builtin-commands.md"};function c(i,t,l,r,n,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="第十五章-内置命令与自定义命令" tabindex="-1">第十五章：内置命令与自定义命令 <a class="header-anchor" href="#第十五章-内置命令与自定义命令" aria-label="Permalink to &quot;第十五章：内置命令与自定义命令&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你不用背命令表——按场景记住 8 个高频命令，并且能把自己的常用提示词变成 <code>/我的命令</code>。</p></div><div class="warning custom-block"><p class="custom-block-title">先纠正一个常见误解</p><p>以前&quot;<strong>命令</strong>（<code>.claude/commands/</code>）&quot;和&quot;<strong>Skill</strong>（<code>.claude/skills/</code>）&quot;是两套东西。<strong>现在它们已经合并了</strong>：自定义命令就是 skill 的一种写法。</p><ul><li>旧写法 <code>.claude/commands/deploy.md</code> 仍然有效，不需要改</li><li>新写的建议用 <code>.claude/skills/deploy/SKILL.md</code></li><li>两者都一样触发 <code>/deploy</code>，行为一致</li></ul><p>所以本章讲&quot;内置命令 + 自定义命令&quot;，第十四章讲 Skill 的完整能力。不用再纠结概念区别。</p></div><h2 id="有哪些命令" tabindex="-1">有哪些命令 <a class="header-anchor" href="#有哪些命令" aria-label="Permalink to &quot;有哪些命令&quot;">​</a></h2><p>在会话里输入 <code>/</code> 就会弹出命令列表，继续输入字母可以模糊筛选。<code>/help</code> 查看帮助。</p><div class="tip custom-block"><p class="custom-block-title">命令菜单会藏东西</p><p>列表里不显示全部。有些命令必须完整输入名字才认（比如 <code>/heapdump</code>），有些要看你的平台和套餐才出现。</p></div><h2 id="按场景记-比背命令表有效" tabindex="-1">按场景记，比背命令表有效 <a class="header-anchor" href="#按场景记-比背命令表有效" aria-label="Permalink to &quot;按场景记，比背命令表有效&quot;">​</a></h2><h3 id="场景一-第一次进一个仓库" tabindex="-1">场景一：第一次进一个仓库 <a class="header-anchor" href="#场景一-第一次进一个仓库" aria-label="Permalink to &quot;场景一：第一次进一个仓库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/init</code></td><td>读项目，生成 <code>CLAUDE.md</code></td></tr><tr><td><code>/memory</code></td><td>编辑 <code>CLAUDE.md</code>、开关自动记忆</td></tr><tr><td><code>/mcp</code></td><td>配置项目需要的 MCP 服务器</td></tr><tr><td><code>/permissions</code></td><td>设置 allow / ask / deny 规则</td></tr></tbody></table><h3 id="场景二-干活过程中" tabindex="-1">场景二：干活过程中 <a class="header-anchor" href="#场景二-干活过程中" aria-label="Permalink to &quot;场景二：干活过程中&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/plan</code></td><td>大改动前先要方案，一行代码不改</td></tr><tr><td><code>/model</code></td><td>切模型（<code>sonnet</code> / <code>opus</code> / <code>haiku</code>）</td></tr><tr><td><code>/effort</code></td><td>调推理强度（<code>low</code> → <code>xhigh</code>）</td></tr><tr><td><code>/context</code></td><td>看上下文被什么占满了</td></tr><tr><td><code>/compact</code></td><td>压缩历史，释放空间</td></tr><tr><td><code>/btw</code></td><td>问个旁支问题，不进对话历史</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>/btw</code> 很实用</p><p>&quot;这个项目为什么用 pnpm？&quot;这种问题用 <code>/btw</code>，答案不会污染主对话的上下文。普通提问则会永久留在历史里。</p></div><h3 id="场景三-提交之前" tabindex="-1">场景三：提交之前 <a class="header-anchor" href="#场景三-提交之前" aria-label="Permalink to &quot;场景三：提交之前&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/diff</code></td><td>看它到底改了什么</td></tr><tr><td><code>/code-review</code></td><td>审查当前分支改动（<code>--fix</code> 可直接改）</td></tr><tr><td><code>/security-review</code></td><td>只看安全漏洞</td></tr></tbody></table><h3 id="场景四-出问题时" tabindex="-1">场景四：出问题时 <a class="header-anchor" href="#场景四-出问题时" aria-label="Permalink to &quot;场景四：出问题时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/rewind</code></td><td>回滚代码和对话到检查点（<code>Esc</code> 两下同效）</td></tr><tr><td><code>/doctor</code></td><td>体检安装、配置、扩展、<code>CLAUDE.md</code> 并给修复建议</td></tr><tr><td><code>/debug</code></td><td>开启日志并从日志里排查问题</td></tr><tr><td><code>/status</code></td><td>看当前模型和配置状态</td></tr></tbody></table><h3 id="场景五-会话之间" tabindex="-1">场景五：会话之间 <a class="header-anchor" href="#场景五-会话之间" aria-label="Permalink to &quot;场景五：会话之间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/clear [名字]</code></td><td>开新对话（可带名字，方便以后找回）</td></tr><tr><td><code>/resume</code></td><td>切到另一个会话</td></tr><tr><td><code>/branch</code></td><td>从当前对话分叉</td></tr><tr><td><code>/recap</code></td><td>生成一句话摘要</td></tr><tr><td><code>/export</code></td><td>导出对话文本</td></tr><tr><td><code>/exit</code></td><td>退出</td></tr></tbody></table><h2 id="自定义命令-把你的话术固定下来" tabindex="-1">自定义命令：把你的话术固定下来 <a class="header-anchor" href="#自定义命令-把你的话术固定下来" aria-label="Permalink to &quot;自定义命令：把你的话术固定下来&quot;">​</a></h2><p>如果你发现自己反复输入同一段指令，就该做成命令。</p><h3 id="最简做法-直接让-claude-帮你建" tabindex="-1">最简做法：直接让 Claude 帮你建 <a class="header-anchor" href="#最简做法-直接让-claude-帮你建" aria-label="Permalink to &quot;最简做法：直接让 Claude 帮你建&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 .claude/skills/ 下创建一个叫 pr-desc 的命令，</span></span>
<span class="line"><span>读当前分支的 git diff，生成一段 PR 描述：</span></span>
<span class="line"><span>改了什么、为什么改、怎么验证。输出直接给 markdown，不要解释过程。</span></span></code></pre></div><p>它会生成 <code>.claude/skills/pr-desc/SKILL.md</code>。之后输入 <code>/pr-desc</code> 就能用。</p><h3 id="手写也很简单" tabindex="-1">手写也很简单 <a class="header-anchor" href="#手写也很简单" aria-label="Permalink to &quot;手写也很简单&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: pr-desc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 根据当前分支的改动生成 PR 描述。在准备提 PR 时使用。</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">读当前分支相对主分支的 diff，按下面格式输出，不要输出其他内容：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 改了什么</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（3 条以内）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 为什么改</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（2 条以内）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 怎么验证</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（可执行的命令）</span></span></code></pre></div><p>两个字段的含义：</p><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td><code>name</code></td><td>命令名，也就是 <code>/pr-desc</code> 里的那部分</td></tr><tr><td><code>description</code></td><td><strong>Claude 靠它判断何时主动用这个 skill</strong>，写清触发时机</td></tr></tbody></table><h3 id="传参数" tabindex="-1">传参数 <a class="header-anchor" href="#传参数" aria-label="Permalink to &quot;传参数&quot;">​</a></h3><p>命令名后面的文字会成为该命令的参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/pr-desc 重点突出数据库迁移的部分</span></span></code></pre></div><h3 id="放哪" tabindex="-1">放哪 <a class="header-anchor" href="#放哪" aria-label="Permalink to &quot;放哪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>生效范围</th></tr></thead><tbody><tr><td><code>.claude/skills/</code></td><td>当前项目，可提交进 git 与团队共享</td></tr><tr><td><code>~/.claude/skills/</code></td><td>你所有项目</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">一个坑</p><p>如果你用的是旧的 <code>.claude/commands/</code> 目录，改完文件需要重启会话才生效；<code>.claude/skills/</code> 支持运行中改动即时生效（<code>/reload-skills</code> 可手动重扫）。</p></div><h2 id="命令行参数-不在会话里用" tabindex="-1">命令行参数（不在会话里用） <a class="header-anchor" href="#命令行参数-不在会话里用" aria-label="Permalink to &quot;命令行参数（不在会话里用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>claude</code></td><td>交互式启动</td></tr><tr><td><code>claude -p &quot;...&quot;</code></td><td>非交互模式，输出后退出，可接管道</td></tr><tr><td><code>claude --continue</code></td><td>接着当前目录上次的会话</td></tr><tr><td><code>claude --resume</code></td><td>从列表恢复</td></tr><tr><td><code>claude --model opus</code></td><td>指定模型</td></tr><tr><td><code>claude --permission-mode plan</code></td><td>指定启动权限模式</td></tr><tr><td><code>claude --worktree &lt;名&gt;</code></td><td>在独立 worktree 里开会话</td></tr><tr><td><code>claude doctor</code></td><td>体检</td></tr><tr><td><code>claude update</code></td><td>升级</td></tr></tbody></table><p>管道用法（适合脚本和 CI）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;这些报错的共同原因是什么？&quot;</span></span></code></pre></div><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>ANTHROPIC_BASE_URL</code></td><td>自定义 API 端点（中转用）</td></tr><tr><td><code>ANTHROPIC_AUTH_TOKEN</code></td><td>中转服务密钥</td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>官方 API 密钥</td></tr><tr><td><code>ANTHROPIC_MODEL</code></td><td>默认模型</td></tr><tr><td><code>CLAUDE_CONFIG_DIR</code></td><td>独立配置目录，用于多账号</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">前缀是 <code>ANTHROPIC_</code>，不是 <code>CLAUDE_</code></p><p>写成 <code>CLAUDE_API_KEY</code> 是无效的，不会报错但也不生效——这是新手最常踩的坑。想永久生效就写进 <code>~/.claude/settings.json</code> 的 <code>env</code> 字段。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 输入 <code>/</code> 没反应？</strong></p><p>A: 确认光标在输入框最前面。命令只在消息<strong>开头</strong>被识别。</p><p><strong>Q: 我的自定义命令不出现？</strong></p><p>A: 检查 <code>SKILL.md</code> 的 frontmatter 有没有 <code>name</code>，以及目录层级对不对（<code>.claude/skills/&lt;名字&gt;/SKILL.md</code>）。改完用 <code>/reload-skills</code> 重扫。</p><p><strong>Q: 一条消息能用多个命令吗？</strong></p><p>A: 能。<code>/command-a /command-b 具体任务</code>，最多串六个，末尾的文字会作为参数传给每个命令。</p><p><strong>Q: <code>/review</code> 和 <code>/code-review</code> 有什么区别？</strong></p><p>A: 没有，<code>/review</code> 是别名。新写的内容统一用 <code>/code-review</code>。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>输入 <code>/</code> 浏览一遍命令列表，用模糊搜索找一个你感兴趣的命令</li><li>用 <code>/btw</code> 问一个旁支问题，然后确认它没出现在 <code>/context</code> 的历史里</li><li>把一段你反复用的提示词做成 <code>/my-check</code> 命令，试用一次</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p><a href="/claude-code-guide/guide/4-advanced-usage/16-hooks-security.html">👉 第十六章：Hooks 与安全配置</a></p>`,53)])])}const b=d(s,[["render",c]]);export{u as __pageData,b as default};
